Translate the following GNU C++14 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <cstdio>
#include <vector>
#include <algorithm>

const int MOD1 = 998244353;
const int MOD2 = 1000000007;
const int BASE = 1000000;

int n, tot, sum[15], ans;
std::vector<int> v[15];

void dfs1(int k, int num) {
    if (k == 7) return;
    tot++;
    int val = ((tot - num) % MOD1 + MOD1) % MOD1;
    v[k].push_back(val);
    sum[k] = (sum[k] + val) % MOD2;
    for (int i = 0; i <= 9; ++i) {
        dfs1(k + 1, num * 10 + i);
    }
}

void dfs2(int x) {
    if (x > n) return;
    if (x * BASE + BASE - 1 <= n && x * BASE * 10 > n) {
        int curTot = tot;
        for (int i = 0, mul = 1; i <= 6; ++i, mul *= 10) {
            int sz = (int)v[i].size();
            int diff = ((curTot - x * mul) % MOD1 + MOD1) % MOD1;
            int pos = (int)(std::lower_bound(v[i].begin(), v[i].end(), (int)(MOD1 - diff)) - v[i].begin());
            ans = (ans + diff * sz + sum[i]) % MOD2;
            ans = (ans - (long long)MOD1 * (sz - pos) % MOD2 + MOD2) % MOD2;
            tot += sz;
        }
        return;
    }
    tot++;
    ans = (ans + ((tot - x) % MOD1 + MOD1) % MOD1) % MOD2;
    for (int i = 0; i <= 9; ++i) {
        dfs2(x * 10 + i);
    }
}

int main() {
    scanf("%d", &n);
    dfs1(0, 0);
    for (int i = 0; i <= 7; ++i) {
        std::sort(v[i].begin(), v[i].end());
    }
    tot = 0;
    for (int i = 1; i <= 9; ++i) {
        dfs2(i);
    }
    printf("%lld\n", ans);
    return 0;
}
